CREATE TABLE IF NOT EXISTS collector_profiles (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,shop_name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,tagline VARCHAR(255) NULL,bio TEXT NULL,avatar_path VARCHAR(255) NULL,banner_path VARCHAR(255) NULL,location VARCHAR(160) NULL,website VARCHAR(255) NULL,status ENUM('pending','approved','suspended') NOT NULL DEFAULT 'pending',is_featured TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_collector_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS collector_items (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,collector_id INT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,slug VARCHAR(220) NOT NULL UNIQUE,listing_type ENUM('sale','trade','wanted','showcase') NOT NULL DEFAULT 'sale',category VARCHAR(80) NOT NULL DEFAULT 'other',franchise VARCHAR(140) NULL,description TEXT NULL,condition_grade VARCHAR(80) NULL,price DECIMAL(10,2) NULL,quantity INT NOT NULL DEFAULT 1,image_path VARCHAR(255) NULL,status ENUM('draft','active','reserved','sold','traded','archived') NOT NULL DEFAULT 'draft',is_featured TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(collector_id,status),CONSTRAINT fk_collect_item_profile FOREIGN KEY(collector_id) REFERENCES collector_profiles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS collector_favorites (user_id BIGINT UNSIGNED NOT NULL,item_id INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,item_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(item_id) REFERENCES collector_items(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS collector_offers (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,item_id INT UNSIGNED NOT NULL,buyer_user_id BIGINT UNSIGNED NOT NULL,offer_type ENUM('cash','trade','message') NOT NULL DEFAULT 'cash',amount DECIMAL(10,2) NULL,trade_details TEXT NULL,message TEXT NULL,status ENUM('pending','accepted','declined','withdrawn','completed') NOT NULL DEFAULT 'pending',seller_note TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(item_id,status),FOREIGN KEY(item_id) REFERENCES collector_items(id) ON DELETE CASCADE,FOREIGN KEY(buyer_user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
